// Wire format of the bus: every event is a JSON envelope, encrypted and
// authenticated with keys derived from the shared channel secret, posted to an
// ntfy-compatible relay under a topic also derived from that secret. The relay
// only ever sees an opaque topic name and ciphertext.
//
// The hooks environment offers SHA-256 alone (no AES), so the cipher is built
// from it: HMAC-SHA256 in counter mode as the keystream, and encrypt-then-MAC
// with HMAC-SHA256 over nonce and ciphertext.

export const WIRE_PREFIX = 'ccbus1:'
export const MAX_TEXT_CHARS = 2000
export const MAX_BODY_BYTES = 4000

export type Envelope =
  | {
      v: 1
      t: 'msg'
      id: string
      from: string
      fromName: string
      to: string
      text: string
      at: number
    }
  | {
      v: 1
      t: 'ctl'
      id: string
      from: string
      fromName: string
      to: string
      model?: string | null
      effort?: Effort | null
      at: number
    }
  | {
      v: 1
      t: 'hello' | 'bye'
      id: string
      from: string
      fromName: string
      kind: 'cloud' | 'local'
      where: string
      ask: boolean
      setup?: string
      at: number
    }

export const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max'] as const
export type Effort = (typeof EFFORTS)[number]

// Short names a peer may send; anything else must look like a model id.
export const MODEL_ALIASES: Readonly<Record<string, string>> = {
  opus: 'claude-opus-5-5',
  sonnet: 'claude-sonnet-5-5',
  haiku: 'claude-haiku-5-5',
  fable: 'claude-fable-5-1',
}

export function resolveModel(raw: string): string | null {
  const name = raw.trim().toLowerCase()
  const alias = MODEL_ALIASES[name]
  if (alias !== undefined) return alias
  return /^claude-[a-z0-9.-]{3,60}(\[1m\])?$/.test(name) ? name : null
}

export function isEffort(value: unknown): value is Effort {
  return typeof value === 'string' && (EFFORTS as readonly string[]).includes(value)
}

export type Channel = { topic: string; encKey: Uint8Array; macKey: Uint8Array }

export type RelayEvent = { id: string; envelope: Envelope }

const encoder = new TextEncoder()
const decoder = new TextDecoder()

const NONCE_BYTES = 16
const TAG_BYTES = 32
const BLOCK = 64

async function digest(bytes: Uint8Array): Promise<Uint8Array> {
  return new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))
}

function concat(...parts: Uint8Array[]): Uint8Array {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0))
  let offset = 0
  for (const p of parts) {
    out.set(p, offset)
    offset += p.length
  }
  return out
}

export async function hmac(key: Uint8Array, message: Uint8Array): Promise<Uint8Array> {
  const k = key.length > BLOCK ? await digest(key) : key
  const padded = concat(k, new Uint8Array(BLOCK - k.length))
  const inner = padded.map(b => b ^ 0x36)
  const outer = padded.map(b => b ^ 0x5c)
  return digest(concat(outer, await digest(concat(inner, message))))
}

async function keystream(key: Uint8Array, nonce: Uint8Array, length: number): Promise<Uint8Array> {
  const blocks: Uint8Array[] = []
  for (let i = 0; i * 32 < length; i++) {
    const counter = new Uint8Array([i >>> 24, (i >>> 16) & 255, (i >>> 8) & 255, i & 255])
    blocks.push(await hmac(key, concat(nonce, counter)))
  }
  return concat(...blocks).slice(0, length)
}

function xor(a: Uint8Array, b: Uint8Array): Uint8Array {
  return a.map((x, i) => x ^ (b[i] ?? 0))
}

function equalTimeSafe(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false
  let diff = 0
  for (let i = 0; i < a.length; i++) diff |= (a[i] ?? 0) ^ (b[i] ?? 0)
  return diff === 0
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('')
}

function toBase64(bytes: Uint8Array): string {
  let binary = ''
  for (const b of bytes) binary += String.fromCharCode(b)
  return btoa(binary)
}

function fromBase64(text: string): Uint8Array {
  const binary = atob(text)
  return Uint8Array.from(binary, c => c.charCodeAt(0))
}

export function isValidSecret(secret: string): boolean {
  return /^[A-Za-z0-9_-]{16,128}$/.test(secret)
}

export function newSecret(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(24))
  return toBase64(bytes).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

export function newId(): string {
  return toHex(crypto.getRandomValues(new Uint8Array(8)))
}

export async function deriveChannel(secret: string): Promise<Channel> {
  const root = encoder.encode(secret)
  const label = (name: string) => hmac(root, encoder.encode('ccbus1:' + name))
  const topic = 'ccbus_' + toHex(await label('topic')).slice(0, 40)
  return { topic, encKey: await label('enc'), macKey: await label('mac') }
}

export async function seal(channel: Channel, envelope: Envelope): Promise<string> {
  const nonce = crypto.getRandomValues(new Uint8Array(NONCE_BYTES))
  const plain = encoder.encode(JSON.stringify(envelope))
  const cipher = xor(plain, await keystream(channel.encKey, nonce, plain.length))
  const tag = await hmac(channel.macKey, concat(nonce, cipher))
  return WIRE_PREFIX + toBase64(concat(nonce, tag, cipher))
}

function isEnvelope(value: unknown): value is Envelope {
  if (typeof value !== 'object' || value === null) return false
  const v = value as Record<string, unknown>
  const hasBase =
    v.v === 1 &&
    typeof v.id === 'string' &&
    typeof v.from === 'string' &&
    typeof v.fromName === 'string' &&
    typeof v.at === 'number'
  if (!hasBase) return false
  if (v.t === 'msg') return typeof v.to === 'string' && typeof v.text === 'string'
  if (v.t === 'ctl') {
    const isModelOk = v.model === undefined || v.model === null || typeof v.model === 'string'
    const isEffortOk = v.effort === undefined || v.effort === null || isEffort(v.effort)
    return typeof v.to === 'string' && isModelOk && isEffortOk
  }
  if (v.t === 'hello' || v.t === 'bye') {
    return (v.kind === 'cloud' || v.kind === 'local') && typeof v.where === 'string'
  }
  return false
}

// Returns null for anything that is not ours or does not authenticate:
// foreign posts to the topic, tampered bodies, other secrets.
export async function open(channel: Channel, body: string): Promise<Envelope | null> {
  if (!body.startsWith(WIRE_PREFIX)) return null
  try {
    const packed = fromBase64(body.slice(WIRE_PREFIX.length))
    if (packed.length <= NONCE_BYTES + TAG_BYTES) return null
    const nonce = packed.slice(0, NONCE_BYTES)
    const tag = packed.slice(NONCE_BYTES, NONCE_BYTES + TAG_BYTES)
    const cipher = packed.slice(NONCE_BYTES + TAG_BYTES)
    const expected = await hmac(channel.macKey, concat(nonce, cipher))
    if (!equalTimeSafe(tag, expected)) return null
    const plain = xor(cipher, await keystream(channel.encKey, nonce, cipher.length))
    const parsed: unknown = JSON.parse(decoder.decode(plain))
    return isEnvelope(parsed) ? parsed : null
  } catch {
    return null
  }
}

export function publishUrl(server: string, channel: Channel): string {
  return `${server.replace(/\/+$/, '')}/${channel.topic}`
}

export function pollUrl(server: string, channel: Channel, since: string): string {
  return `${publishUrl(server, channel)}/json?poll=1&since=${encodeURIComponent(since)}`
}

// ntfy answers a poll as newline-delimited JSON events.
export async function parsePoll(
  channel: Channel,
  ndjson: string,
): Promise<{ events: RelayEvent[]; cursor: string | null }> {
  const events: RelayEvent[] = []
  let cursor: string | null = null
  for (const line of ndjson.split('\n')) {
    if (line.trim() === '') continue
    let raw: unknown
    try {
      raw = JSON.parse(line)
    } catch {
      continue
    }
    const r = raw as { id?: unknown; event?: unknown; message?: unknown }
    if (r.event !== 'message' || typeof r.id !== 'string') continue
    cursor = r.id
    if (typeof r.message !== 'string') continue
    const envelope = await open(channel, r.message)
    if (envelope !== null) events.push({ id: r.id, envelope })
  }
  return { events, cursor }
}

export function byteLength(text: string): number {
  return encoder.encode(text).length
}

